def solution(input_str):
    import sys
    sys.setrecursionlimit(20000)

    def solve(n, m, k):
        # Memoization cache
        memo = {}

        def dp(height, width, target):
            # If we want 0 squares, no cost
            if target == 0:
                return 0
            # If the piece size equals target, no cost to take it
            if height * width == target:
                return 0

            key = (height, width, target)
            if key in memo:
                return memo[key]

            result = float('inf')

            # Try breaking horizontally at position 'h' from top (1 to height-1)
            for h in range(1, height):
                cost = width * width  # Cost = (column width)²

                # Try all ways to split target between the two pieces
                for t1 in range(min(target, h * width) + 1):
                    t2 = target - t1

                    # Check if t2 fits in bottom piece
                    if t2 <= (height - h) * width:
                        c1 = dp(h, width, t1)
                        c2 = dp(height - h, width, t2)
                        if c1 + c2 < float('inf'):
                            result = min(result, cost + c1 + c2)

            # Try breaking vertically at position 'w' from left (1 to width-1)
            for w in range(1, width):
                cost = height * height  # Cost = (row height)²

                # Try all ways to split target between the two pieces
                for t1 in range(min(target, height * w) + 1):
                    t2 = target - t1

                    # Check if t2 fits in right piece
                    if t2 <= height * (width - w):
                        c1 = dp(height, w, t1)
                        c2 = dp(height, width - w, t2)
                        if c1 + c2 < float('inf'):
                            result = min(result, cost + c1 + c2)

            memo[key] = result
            return result

        return dp(n, m, k)

    lines = input_str.strip().split('\n')
    t = int(lines[0])
    results = []

    for i in range(1, len(lines)):
        if lines[i].strip():
            n, m, k = map(int, lines[i].split())
            results.append(str(solve(n, m, k)))

    return '\n'.join(results)
