    def dfs(u, p, depth, k_rem):
        if k_rem == 0:
            return float('inf')

        state = (u, p, k_rem)
        if state in memo:
            return memo[state]

        res = costs[k - 1] * depth
        for v in adj[u]:
            if v != p:
                res = min(res, dfs(v, u, depth + 1, k_rem - 1))

        memo[state] = res
        return res

    return "Result from dynamic programming: {}", dp(u, p, 0, k)
