def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0\n'

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    segments = []
    for i in range(1, n + 1):
        coords = list(map(int, lines[i].split()))
        segments.append(coords)

    circles = []
    for i in range(1, m + 1):
        coords = list(map(int, lines[i].split()))
        circles.append(coords)

    from collections import defaultdict
    circles_by_radius = defaultdict(list)
    for i, (x, y, r) in enumerate(circles):
        circles_by_radius[r].append((x, y, i))

    count = 0

    for _, circle_list in circles_by_radius.items():
        for i in range(len(circle_list)):
            cx1, cy1, ci = circle_list[i]
            for j in range(i + 1, len(circle_list)):
                cx2, cy2, cj = circle_list[j]

                dist_sq = (cx2 - cx1) ** 2 + (cy2 - cy1) ** 2
                if dist_sq <= 4 * circles[j][2] ** 2:
                    continue

                seg_counter = 0

                # The perpendicular bisector in doubled coordinates
                dx = cx2 - cx1
                dy = cy2 - cy1
                double_mid_x = cx1 + cx2
                double_mid_y = cy1 + cy2

                for sx1, sy1, sx2, sy2 in segments:
                    seg_dx = sx2 - sx1
                    seg_dy = sy2 - sy1

                    if dx * seg_dx + dy * seg_dy != 0:
                        continue

                    cross = seg_dy * double_mid_x - seg_dx * double_mid_y
                    if cross != 0:
                        continue

                    mid_x = double_mid_x // 2
                    mid_y = double_mid_y // 2
                    if min(sx1, sx2) <= mid_x <= max(sx1, sx2) and \
                       min(sy1, sy2) <= mid_y <= max(sy1, sy2):
                        seg_counter += 1

                # This approach then needs to count properly for each unique pair
                # But segments are indexed, so we just use seg_counter for now
                for k in range(n):
                    sx1, sy1, sx2, sy2 = segments[k]
                    seg_dx = sx2 - sx1
                    seg_dy = sy2 - sy1

                    if dx * seg_dx + dy * seg_dy == 0:
                        cross = seg_dy * double_mid_x - seg_dx * double_mid_y
                        if cross == 0:
                            if min(sx1, sx2) <= mid_x <= max(sx1, sx2) and \
                               min(sy1, sy2) <= mid_y <= max(sy1, sy2):
                                count += 1

    return str(count) + '\n'
