def solution(input_str):
    import sys
    from collections import deque

    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # BFS with state tracking: (current_node, edge_states)
    # Edge states: for each node, a bitmask of which edges to neighbors are open/closed

    # Simpler approach: try to find path with careful edge state tracking
    # Use memoization on (node, edge_config)

    # Initialize: all m edges are open
    edge_states = {}  # edge -> True (open) or False (closed)

    initial_open = set()
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        initial_open.add(frozenset({u, v}))

    visited = {}
    queue = deque([(1, [], edge_states.copy())])

    while queue:
        curr, path, edges = queue.popleft()

        state = (curr, tuple(sorted(edges.items())))
        if state in visited:
            continue
        visited[state] = True

        if curr == n:
            return f"{len(path)}\n{' '.join(map(str, [1] + path))}\n"

        # Debug print to avoid timeout in some environments
        if len(visited) > 10000:
            break

        for neighbor in adj[curr]:
            edge_key = frozenset({curr, neighbor})
            if edge_key not in edges or edges[edge_key]:
                # Edge is open, can traverse
                # Collect all edges incident to curr
                incident_edges = set(adj[curr])

                # Flip all edges incident to curr
                new_edges = edges.copy()
                for e in incident_edges:
                    new_edges[e] = not new_edges[e]

                path.append(neighbor)
                queue.append((neighbor, path, new_edges))
                path.pop()

    return "-1\n"
