import sys

def solution(input_str):
    """
    Interactive problem to find two numbers (a, b) where 1 <= a, b <= n
    with at most 600 queries.

    We use binary search on both dimensions independently.
    """
    import io

    input_stream = io.StringIO(input_str)
    output_lines = []

    def flush_output():
        for line in output_lines:
            print(line)
        sys.stdout.flush()

    def read_response():
        line = input_stream.readline().strip()
        if not line:
            return 0
        return int(line)

    # Read n from input
    lines = input_stream.read().split('\n')
    n = int(lines[0])

    # Binary search for a
    a_low, a_high = 1, n
    b = 1  # Temporary value for searching a

    while a_low < a_high:
        mid_a = (a_low + a_high + 1) // 2
        output_lines.append(f"{mid_a} {b}")
        flush_output()  # In actual interactive, this wouldn't be needed

        response = read_response()

        if response == 0:
            final_a = mid_a
            break
        elif response == 1:  # x < a
            a_low = mid_a
        else:  # x > a or reply is 2 or 3, so a could be lower
            a_high = mid_a - 1
    else:
        final_a = a_low

    # Now find b with known a
    b_low, b_high = 1, n

    while b_low < b_high:
        mid_b = (b_low + b_high + 1) // 2
        output_lines.append(f"{final_a} {mid_b}")
        flush_output()

        response = read_response()

        if response == 0:
            final_b = mid_b
            break
        elif response == 2:  # y < b
            b_low = mid_b
        else:
            b_high = mid_b - 1
    else:
        final_b = b_low

    return '\n'.join(output_lines) + '\n'
