def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    def get_prime_factors(num):
        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return factors

    if n == 1:
        return str(b)

    all_primes = set()
    for num in arr:
        all_primes.update(get_prime_factors(num))

    ans = float('inf')

    for g in all_primes:
        non_div = [i for i, x in enumerate(arr) if x % g != 0]

        if not non_div:
            cost = 0
        else:
            segments = []
            i = 0
            while i < len(non_div):
                j = i
                while j + 1 < len(non_div) and non_div[j + 1] == non_div[j] + 1:
                    j += 1
                segments.append((non_div[i], non_div[j]))
                i = j + 1

            cost_change = len(non_div) * b
            cost_remove = float('inf')
            for (start, end) in segments:
                seg_len = end - start + 1
                if seg_len < n:
                    cost_remove = min(cost_remove, seg_len * a)

            if cost_remove != float('inf'):
                cost = min(cost_change, cost_remove)
            else:
                cost = cost_change

        ans = min(ans, cost)

    return str(ans)
