import math
from functools import lru_cache

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return math.factorial(n) // (math.factorial(k) * math.factorial(n - k))

def count_numbers_with_k_bits(x, k):
    """
    Count numbers in [1, x] with exactly k bits set in their binary representation.
    """
    if x <= 0:
        return 0
    if k == 0:
        return 0

    result = 0
    binary_x = bin(x)[2:]
    n_bits = len(binary_x)

    for i in range(n_bits):
        bit_at_position = int(binary_x[i])

        if ones_left <= 0:
            break

        remaining_bits = n_bits - (i + 1)

        if bit_at_position == 1:
            # We can place 0 at this position and complete the rest with remaining bits chosen from remaining_bits positions
            result += combinations(remaining_bits, ones_left)

            # Then we place 1 and continue
            ones_left -= 1
        else:
            # x has 0 at this position, we must also place 0 (or it would be > x)
            pass

    return result

def find_n_for_m_k(m, k):
    """
    Find n such that in [n+1, 2n], exactly m numbers have exactly k bits set.
    """
    def count_range(n):
        return count_numbers_with_k_bits(2 * n, k) - count_numbers_with_k_bits(n, k)

    # Binary search for n
    left, right = 1, 10**18

    # First check if zero is possible
    if m == 0 and k > 0:
        # Return minimal n where count is 0
        answer = 1
        while count_range(answer) != 0 and answer < 10**18:
            answer *= 2
        return answer

    while left <= right:
        mid = (left + right) // 2
        cnt = count_range(mid)
        if cnt == m:
            return mid
        elif cnt > m:
            right = mid - 1
        else:
            left = mid + 1

    # If not found, double check by manually searching small values
    # (fallback for edge cases)
    for candidate in range(1, min(left * 2, 10**18 + 1)):
        if count_range(candidate) == m:
            return candidate

    return left

