    edges = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        u, v, k = int(parts[0]), int(parts[1]), int(parts[2])
        visions = []
        for j in range(k):
            visions.append(int(parts[3 + j]))
        edges.append((u, v, visions))

    # Build adjacency: adj[a][b] = True if edge exists from a to b
    adj = [[False] * (n + 1) for _ in range(n + 1)]
    for u, v, visions in edges:
        adj[u][v] = True

    # For S2: count paths of each length 1 to 2n that match a vision sequence
    # A path matches if it equals some vision sequence from an edge

    # Check if a sequence can be formed by actual edges
    def is_valid_path(shop_sequence):
        if len(shop_sequence) < 2:
            return False
        # A path needs at least 2 shops (start and end) for an edge
        # But vision sequence could be length 1
        if len(shop_sequence) == 1:
            # Single shop - can it be a valid vision for an edge?
            # Return True if we can pick any edge with k=0 vision
            for u, v, visions in edges:
                if len(visions) == 0:
                    return True
            return False
        # Check consecutive edges exist
        for i in range(len(shop_sequence) - 1):
            if not adj[shop_sequence[i]][shop_sequence[i + 1]]:
                return False
        return True

    MOD = 1000000007

    # Count for each length
    result = []
    for length in range(1, 2 * n + 1):
        count = 0

        # Generate all shop sequences of this length and check
        def walk(pos, length_list, depth):
            nonlocal count
            if depth == length_list:
                # Check if this sequence is valid
                if is_valid_path(length_list[:]):
                    count += 1
                return

            for next_shop in range(1, n + 1):
                length_list.append(next_shop)
                if pos > 0 and adj[length_list[-2]][next_shop]:
                    # Can we actually trace back the last edge to origin
                    # Actually, for vision matching, we need to verify against actual edges
                    walk(pos + 1, length_list, depth + 1)
                length_list.pop()

        # Simpler: enumerate all possible paths and check if they match any vision
        if length == 1:
            # Single element paths - check if there are edges with vision length 0
            if any(len(v) == 0 for _, _, v in edges):
                count += n
        else:
            # For length >= 2, need to match actual vision sequences
            for u, v, visions in edges:
                if len(visions) == length and is_valid_path(visions):
                    if isnearby(visions):
                        count += 1

        result.append(str(count % MOD))

    return '\n'.join(result)
