        disc[u] = low[u] = timer[0]
        timer[0] += 1
        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                low[u] = min(low[u], disc[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]:
                    bridges.append((u, v))

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Union-Find for contracting bridge-blocks
    parent = list(range(n + 1))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    for u, v in bridges:
        union(u, v)

    # Build block tree
    comp_to_node = {}
    node_vals = {}
    comp_count = 0
    for i in range(1, n + 1):
        root = find(i)
        if root not in comp_to_node:
            comp_to_node[root] = comp_count
            node_vals[comp_count] = i
            comp_count += 1

    tree = [[] for _ in range(comp_count)]
    for u, v in bridges:
        cu = comp_to_node[find(u)]
        cv = comp_to_node[find(v)]
        if cu != cv:
            tree[cu].append(cv)
            tree[cv].append(cu)

    # Count degrees in block tree
    degree = [0] * comp_count
    for u in range(comp_count):
        for v in tree[u]:
            degree[u] += 1

    leaves = [i for i in range(comp_count) if degree[i] == 1]

    if comp_count == 1:
        return '0'

    result = []
    result.append(str(len(leaves) // 2))

    if len(leaves) > 0:
        leaves.sort(key=lambda x: node_vals[x])
        added = 0
        for i in range(0, len(leaves), 2):
            if i + 1 < len(leaves):
                u = node_vals[leaves[i]]
                v = node_vals[leaves[i + 1]]
                result.append(f'{u} {v}')

    return '\n'.join(result)
