    for i in range(n):
        x, y = map(float, lines[1 + i].split())
        vertices.append((x, y))

    def point_in_polygon(px, py, verts, allowed_on_boundary=False):
        """Ray casting algorithm to check point inside polygon. Boundary belongs to polygon."""
        inside = False
        n_verts = len(verts)
        for i in range(n_verts):
            x1, y1 = verts[i]
            x2, y2 = verts[(i + 1) % n_verts]
            # Check if point is on the edge
            cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
            on_edge = abs(cross) < 1e-10
            if on_edge and abs(x - x1) > 1e-10 and abs(y - y1) > 1e-10:
                continue
            if (y1 > py) != (y2 > py):
                xinters = (x2 - x1) * (py - y1) / (y2 - y1 + 1e-10) + x1
                if xinters > px:
                    inside = not inside
        return inside

    def dist_sq(ax, ay, bx, by):
        return (ax - bx) ** 2 + (ay - by) ** 2

    def dist(ax, ay, bx, by):
