import os

def solution(input_str):
    """
    Water mixing problem: maximize flow while achieving target temperature T.

    Strategy:
    - Use all taps with ti == T (they don't affect balance)
    - Balance taps with ti < T against taps with ti > T
    - For taps with same efficiency (|ti-T|), use optimally to maximize flow
    """
    lines = input_str.strip().split('\n')
    n, T = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    t = list(map(int, lines[2].split()))

    same_flow = 0
    cold = []  # (conversion_factor, max_amount) where factor = T - ti
    hot = []   # (conversion_factor, max_amount) where factor = ti - T

    for i in range(n):
        if t[i] == T:
            same_flow += a[i]
        elif t[i] < T:
            cold.append((T - t[i], a[i]))
        elif t[i] > T:
            hot.append((t[i] - T, a[i]))

    if not cold and not hot:
        return same_flow

    # Sort by efficiency (lower factor = more efficient to produce balance)
    cold.sort(key=lambda x: x[0])
    hot.sort(key=lambda x: x[0])

    total = same_flow

    # Try using cold taps first, finding how much hot capacity is needed
    for cf_c, ac in cold:
        used_c = ac
        if hot:
            needed_h = used_c * cf_c  # hot flow needed
            min_h_factor = hot[0][0]  # most efficient hot tap
            if needed_h > 0:
                max_h = needed_h / min_h_factor
                if max_h <= hot[0][1]:
                    total += needed_h / min_h_factor
            else:
                total += used_c
        else:
            total += used_c

    return total
