def solve(n, s1, s2, x):
    def check(D):
        # Track states: (waiting_rider_positions, which_rider_is_at_current_pos)
        # Actually, we track the possible positions where the non-actively delivering rider could be

        # After delivery i, one rider is at x[i], the other is waiting at some position from earlier

        # States: set of (waiting_positions, who_is_active)
        # who_is_active = 0 means rider 0 is at x[i], rider 1 is waiting somewhere

        active = set()  # indicates if we have valid states (empty means no valid states)

        # Initial: before first delivery
        # Try both: rider 0 delivers first or rider 1 delivers first

        if abs(x[0] - s1) <= D:
            # rider 0 can deliver x[0]
            active.add({s2})  # rider 1 waits at starting position
            active.add({s2, x[0]})
        if abs(x[0] - s2) <= D:
            # rider 1 can deliver x[0]
            active.add({s1})  # rider 0 waits at starting position

        for i in range(1, n):
            next_target = x[i]
            new_active = set()

            if not active:
                return False

            for waiting in active:
                # Current position of the rider who just delivered = x[i-1]

                # Option 1: same rider delivers again from x[i-1] to x[i]
                if abs(next_target - x[i-1]) <= D:
                    new_waiting = {p for p in waiting}
                    new_waiting.add(x[i-1])
                    new_waiting.add(x[i])
                    new_active.add(new_waiting)

                # Option 2: waiting rider delivers from some position p to x[i]
                for p in waiting:
                    if abs(next_target - p) <= D:
                        new_active.add(waiting | {p, x[i]})
                        break  # One valid assignment is enough

            if not new_active:
                return False
            active = new_active

        return len(active) > 0

    # Binary search for the answer
    left = 0
    right = 2 * 10**9  # Maximum possible coordinate difference
    ans = right

    while left <= right:
        mid = (left + right) // 2
        if check(mid):
            ans = mid
            right = mid - 1
        else:
            left = mid + 1

    return ans

