    s2 = input_data[2]
    x = input_data[3:] if len(input_data) > 3 else []

    def check(D):
        # After delivery i->i+1, active rider at x[i], waiting has set of positions

        # Initial state after first delivery
        waiting = {}  # waiting[r] = set of possible positions where rider r is waiting
        active = set()  # set of rides who can deliver next

        if abs(x[0] - s1) <= D:
            active.add((0, {s2}))
        if abs(x[0] - s2) <= D:
            active.add((1, {s1}))

        if not active:
            return False

        # active is set of (rider_at_current, waiting_positions)
        for _, waiting_set in active:
            pass

        for i in range(1, n):
            next_target = x[i]
            next_active = set()
            current_pos = x[i-1]

            valid_found = False

            for rider_pos in active:
                # Active rider at current_pos, waiting at rider_set[rider_pos]
                if rider_pos == 0:
                    waiting_set = rider_set[1]
                else:
                    waiting_set = rider_set[0]

                # Same rider delivers again from current_pos
                if abs(next_target - current_pos) <= D:
                    new_waiting = list(waiting_set) + [current_pos, next_target]
                    next_active.add((rider_pos + 3, set(new_waiting)))
                    valid_found = True

                # Waiting rider delivers from some position p
                for p in waiting_set:
                    if abs(next_target - p) <= D:
                        new_waiting = list(waiting_set) + [next_target]
                        next_active.add(((rider_pos + 3) ^ 1, set(new_waiting)))
                        valid_found = True
                        break

            if not valid_found:
                return False

            active = next_active

        return len(active) > 0

    def solve(n, s1, s2, x):
        lo, hi = 0, 2 * 10**9
        ans = hi
        while lo <= hi:
            mid = (lo + hi) // 2
            if check(mid):
                ans = mid
                hi = mid - 1
            else:
                lo = mid + 1
        return ans

    return str(solve(n, s1, s2, x))
