# Explanation of the solution approach:
# 
# Problem: Count numbers in range [x, y] (both same length d) that are "half-occurrences" in string s.
# A number of length d is a half-occurrence if it contains ANY substring of length >= ceil(d/2) that appears in s.
#
# Strategy:
# - Count numbers that are NOT half-occurrences (avoid all substrings of length ceil(d/2) from s)
# - Answer = total_count - non_half_occurrence_count
#
# Use digit DP with Aho-Corasick automaton to efficiently check if any length-L substring matches a pattern from s.

import math
from collections import deque

MOD = 10**9 + 7

class AhoCorasick:
    def __init__(self, patterns):
        # pattern nodes, same pattern should have end=True
        self.trie = [{'next': {}, 'fail': 0, 'end': False}]
        self.num_states = 1

        for pattern in patterns:
            node = 0
            for c in pattern:
                if c not in self.trie[node]['next']:
                    self.trie[node]['next'][c] = len(self.trie)
                    self.trie.append({'next': {}, 'fail': 0, 'end': False})
                node = self.trie[node]['next'][c]
            self.trie[node]['end'] = True

        # Build failure links
        queue = deque()
        for c, n in self.trie[0]['next'].items():
            self.trie[n]['fail'] = 0
            queue.append(n)

        while queue:
            r = queue.popleft()
            for c, nc in self.trie[r]['next'].items():
                queue.append(nc)
                f = self.trie[r]['fail']
                while f != 0 and c not in self.trie[f]['next']:
                    f = self.trie[f]['fail']
                if c in self.trie[f]['next']:
                    self.trie[nc]['fail'] = self.trie[f]['next'][c]
                else:
