# Computational geometry solution
def point_on_segment(px, py, x1, y1, x2, y2):
    cross = (x2 - x1) * (py - y1) - (y2 - y1) * (px - x1)
    if abs(cross) > 1e-9:
        return False
    dot = (px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)
    if dot < 0:
        return False
    len_sq = (x2 - x1) ** 2 + (y2 - y1) ** 2
    if len_sq > 1e-10 and dot >= len_sq:
        return False
    return True

def distance_to_segment(px, py, x1, y1, x2, y2, r):
    # Distance from point (px, py) to segment (x1,y1)-(x2,y2), clipped to radius
    if point_on_segment(px, py, x1, y1, x2, y2):
        return 0.0

    xd = px - x1
    yd = py - y1
    seg_len_sq = x2 * x2 - 2 * x1 * x2 + x1 * x1 + y2 * y2 - 2 * y1 * y2 + y1 * y1
    seg_sq = (x2 - x1) ** 2 + (y2 - y1) ** 2
    if abs(seg_sq) < 1e-12:
        return math.sqrt(xd * xd + yd * yd)

    t = max(0, min(1, ((xd * (x2 - x1)) + yd * (y2 - y1)) / seg_sq))
    proj_x = x1 + t * (x2 - x1)
    proj_y = y1 + t * (y2 - y1)
    d2 = (px - proj_x) ** 2 + (py - proj_y) ** 2
    return math.sqrt(d2)

def point_in_triangle(tx, ty, ax, ay, bx, by, cx, cy):
    if (bx - ax) * (ty - ay) - (by - ay) * (tx - ax) < 0:
        return (cx - ax) * (ty - ay) - (cy - ay) * (tx - ax) < 0
    return (cx - ax) * (ty - ay) - (cy - ay) * (tx - ax) >= 0

def point_polygon_cross(poly_points, px, py):
    inside = False
    for i in range(len(poly_points)):
        x1, y1 = poly_points[i]
        x2, y2 = poly_points[(i + 1) % len(poly_points)]
        if ((y1 > py) != (y2 > py)):
            xinters = (px - x1) * (y2 - y1) / (py - y1) + x1
            if abs(y2 - y1) > 1e-12 and xinters <= px:
                inside = not inside
    return inside

def dist_sq(px, py, x, y):
