def polygon_area(poly_points):
    n = len(poly_points)
    if n < 3:
        return 0.0
    area = 0.0
    for i in range(n):
        j = (i + 1) % n
        area += poly_points[i][0] * poly_points[j][1]
        area -= poly_points[j][0] * poly_points[i][1]
    return abs(area) / 2.0

