    # Check if polygon is inside circle but center not in polygon (won't happen if all vertices inside)
    # Check if any vertex is inside the circle
    any_vertex_inside = any(dist_sq(cx, cy, p[0], p[1]) <= r**2 + 1e-9 for p in poly_points)

    return 0.0 if not any_vertex_inside else 0.0

